<?php
declare(strict_types=1);
namespace MailMcp;

final class Panel
{
    public function __construct(private Store $store, private array $config) {}
    public function handle(string $path, string $method): bool
    {
        if (!str_starts_with($path,'/admin') && !in_array($path,['/login','/logout','/authorize','/authorize/approve','/token','/register','/.well-known/oauth-authorization-server'],true)) return false;
        if (session_status()!==PHP_SESSION_ACTIVE) { session_name('mailmcp_admin'); session_set_cookie_params(['httponly'=>true,'secure'=>true,'samesite'=>'Lax','path'=>'/']); session_start(); }
        if ($path==='/register') { $this->registerClient(); return true; }
        if ($path==='/token') { $this->token(); return true; }
        if ($path==='/.well-known/oauth-authorization-server') { $this->metadata(); return true; }
        if ($path==='/authorize/approve') { $this->approve($method); return true; }
        if ($path==='/authorize') { $this->authorize($method); return true; }
        if ($path==='/login') { $this->login($method); return true; }
        if ($path==='/logout') { $this->requirePost($method); unset($_SESSION['admin_id']); header('Location: /admin'); return true; }
        $this->admin($path,$method); return true;
    }
    private function admin(string $path,string $method): void
    {
        if (!$this->store->hasAdmin()) { if($method==='POST'&&$path==='/admin/setup') { $this->setup(); return; } $this->page('Create admin account',$this->form('/admin/setup',[['email','Email','email'],['password','Password (12+ characters)','password'],['confirm','Confirm password','password']])); return; }
        if (!$this->signedIn()) { header('Location: /login'); return; }
        if($path==='/admin/domain/delete'&&$method==='POST'){ $this->csrf(); $d=strtolower(trim($_POST['domain']??''));$this->store->deleteDomain($d);header('Location: /admin');return; }
        if($path==='/admin/domain'&&$method==='POST'){ $this->saveDomain();return; }
        if($path==='/admin/client/delete'&&$method==='POST'){ $this->csrf();$this->store->deleteClient($_POST['client_id']??'');header('Location: /admin#oauth');return; }
        if($path==='/admin/password'&&$method==='POST'){ $this->changePassword();return; }
        if($path==='/admin/oauth'&&$method==='POST'){ $this->csrf();$ttl=max(300,min(2592000,(int)($_POST['token_ttl']??3600)));$this->store->saveSetting('oauth_token_ttl',(string)$ttl);$this->store->saveSetting('oauth_scope','mail.send');header('Location: /admin#oauth');return; }
        $this->dashboard();
    }
    private function setup(): void { $this->csrf();$email=filter_var(strtolower(trim($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');if(!$email||strlen($pass)<12||$pass!==($_POST['confirm']??'')){ $this->page('Create admin account','<p>Use a valid email and a matching password of at least 12 characters.</p>'.$this->form('/admin/setup',[['email','Email','email'],['password','Password (12+ characters)','password'],['confirm','Confirm password','password']]));return;}$this->store->createAdmin($email,$pass);session_regenerate_id(true);$_SESSION['admin_id']=1;$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /admin'); }
    private function login(string $method): void { if($this->signedIn()){header('Location: /admin');return;}if($method==='POST'){$this->csrf();$admin=$this->store->adminByEmail($_POST['email']??'');if($admin&&password_verify((string)($_POST['password']??''),$admin['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$admin['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: '.($_SESSION['after_login']??'/admin'));unset($_SESSION['after_login']);return;}$error='<p class="error">Email or password was incorrect.</p>'; }else{$error='';}$this->page('Sign in',$error.$this->form('/login',[['email','Email','email'],['password','Password','password']])); }
    private function saveDomain(): void { $this->csrf();$domain=strtolower(trim($_POST['domain']??''));if(!preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/',$domain)){$this->page('Invalid domain','<p>Enter a valid domain name.</p><p><a href="/admin">Back</a></p>');return;}$old=$this->store->domain($domain)??[];$password=(string)($_POST['smtp_password']??'');if($password==='')$password=$this->decrypt((string)($old['password_enc']??''));$record=['from_name'=>trim($_POST['from_name']??''),'smtp_host'=>trim($_POST['smtp_host']??''),'smtp_port'=>max(1,min(65535,(int)($_POST['smtp_port']??587))),'smtp_encryption'=>in_array($_POST['smtp_encryption']??'tls',['tls','ssl','none'],true)?$_POST['smtp_encryption']:'tls','smtp_username'=>trim($_POST['smtp_username']??''),'password_enc'=>$this->encrypt($password),'hourly_limit'=>max(1,(int)($_POST['hourly_limit']??40)),'daily_limit'=>max(1,(int)($_POST['daily_limit']??200)),'max_recipients_per_message'=>max(1,(int)($_POST['max_recipients']??10))];if(!$record['smtp_host']||!$record['smtp_username']||!$password){$this->page('Missing SMTP settings','<p>SMTP host, username, and password are required.</p><p><a href="/admin">Back</a></p>');return;}$this->store->saveDomain($domain,$record);header('Location: /admin#domains'); }
    private function changePassword(): void { $this->csrf();$admin=$this->store->pdo()->query('SELECT * FROM admins LIMIT 1')->fetch();if(!$admin||!password_verify((string)($_POST['current_password']??''),$admin['password_hash'])||strlen((string)($_POST['new_password']??''))<12||($_POST['new_password']??'')!==($_POST['confirm']??'')){$this->page('Password not changed','<p>Check current password and use a matching new password of at least 12 characters.</p><p><a href="/admin">Back</a></p>');return;}$s=$this->store->pdo()->prepare('UPDATE admins SET password_hash=? WHERE id=?');$s->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$admin['id']]);$this->page('Password updated','<p>Your password was updated.</p><p><a href="/admin">Continue</a></p>'); }
    private function dashboard(): void { $domains=$this->store->domains();$rows='';foreach($domains as $domain=>$d){$name=$this->esc($domain);$rows.='<tr><td>'.$name.'</td><td>'.(int)($d['smtp_port']??0).'</td><td>'.(int)($d['hourly_limit']??0).'/h · '.(int)($d['daily_limit']??0).'/day</td><td><form method="post" action="/admin/domain/delete">'.$this->csrfField().'<input type="hidden" name="domain" value="'.$name.'"><button>Remove</button></form></td></tr>';}$clients='';foreach($this->store->clients() as $c){$m=json_decode($c['metadata'],true)?:[];$id=$this->esc($c['client_id']);$clients.='<tr><td><code>'.$id.'</code></td><td>'.$this->esc(implode(', ',array_slice($m['redirect_uris']??[],0,2))).'</td><td><form method="post" action="/admin/client/delete">'.$this->csrfField().'<input type="hidden" name="client_id" value="'.$id.'"><button>Revoke</button></form></td></tr>';}$ttl=(int)$this->store->setting('oauth_token_ttl','3600');$domainForm=$this->form('/admin/domain',[['domain','Sending domain','text'],['from_name','From name','text'],['smtp_host','SMTP host','text'],['smtp_port','SMTP port','number'],['smtp_encryption','Encryption: tls / ssl / none','text'],['smtp_username','SMTP username','text'],['smtp_password','SMTP password (blank keeps existing)','password'],['hourly_limit','Hourly message limit','number'],['daily_limit','Daily message limit','number'],['max_recipients','Recipients per message limit','number']]);$html='<p>Signed in as administrator. MCP endpoint: <code>'.$this->esc($this->config['base_url']).'</code></p><form method="post" action="/logout">'.$this->csrfField().'<button>Sign out</button></form><h2 id="domains">SMTP domains</h2><table><tr><th>Domain</th><th>Port</th><th>Rate caps</th><th></th></tr>'.$rows.'</table><h3>Add or update domain</h3>'.$domainForm.'<h2 id="oauth">OAuth access</h2><p>ChatGPT clients register dynamically. Authenticate through the administrator login, then authorize the <code>mail.send</code> scope.</p><form method="post" action="/admin/oauth">'.$this->csrfField().'<label>Access token lifetime (seconds)<input name="token_ttl" type="number" min="300" max="2592000" value="'.$ttl.'"></label><button>Save OAuth setting</button></form><h3>Registered OAuth clients</h3><table><tr><th>Client ID</th><th>Redirect URI</th><th></th></tr>'.$clients.'</table><h2>Change admin password</h2>'.$this->form('/admin/password',[['current_password','Current password','password'],['new_password','New password (12+ characters)','password'],['confirm','Confirm new password','password']]);$this->page('Mail MCP administration',$html); }
    private function registerClient(): void { $this->jsonHeaders();if($_SERVER['REQUEST_METHOD']!=='POST'){$this->jsonError(405,'invalid_client_metadata');return;}$data=json_decode((string)file_get_contents('php://input'),true);$uris=$data['redirect_uris']??[];if(!is_array($uris)||!$uris||count($uris)>20){$this->jsonError(400,'invalid_redirect_uri');return;}foreach($uris as $uri){$p=parse_url($uri);if(!is_array($p)||(!in_array($p['scheme']??'', ['https','http'],true))||(($p['scheme']??'')==='http'&&!in_array($p['host']??'',['localhost','127.0.0.1','::1'],true))){$this->jsonError(400,'invalid_redirect_uri');return;}}$id='client_'.bin2hex(random_bytes(20));$data['client_id']=$id;$data['token_endpoint_auth_method']='none';$data['grant_types']=['authorization_code'];$data['response_types']=['code'];$this->store->registerClient($id,$data);http_response_code(201);echo json_encode($data,JSON_UNESCAPED_SLASHES); }
    private function metadata(): void { $u=$this->config['base_url'];$this->jsonHeaders();echo json_encode(['issuer'=>$u,'authorization_endpoint'=>$u.'/authorize','token_endpoint'=>$u.'/token','registration_endpoint'=>$u.'/register','response_types_supported'=>['code'],'grant_types_supported'=>['authorization_code'],'code_challenge_methods_supported'=>['S256'],'token_endpoint_auth_methods_supported'=>['none'],'scopes_supported'=>['mail.send'],'client_id_metadata_document_supported'=>false],JSON_UNESCAPED_SLASHES); }
    private function authorize(string $method): void { if($method!=='GET'){$this->httpError(405,'Use GET.');return;}$q=$_GET;$client=$this->store->client((string)($q['client_id']??''));$redirect=(string)($q['redirect_uri']??'');$challenge=(string)($q['code_challenge']??'');if(!$client||!in_array($redirect,$client['redirect_uris']??[],true)||($q['response_type']??'')!=='code'||($q['code_challenge_method']??'')!=='S256'||!preg_match('/^[A-Za-z0-9_-]{43,128}$/',$challenge)||!in_array('mail.send',preg_split('/\s+/',(string)($q['scope']??'')),true)){ $this->httpError(400,'Invalid OAuth authorization request.');return;}if(!$this->signedIn()){$_SESSION['after_login']='/authorize?'.http_build_query($q);header('Location: /login');return;}$this->csrfToken();
        $_SESSION['pending_auth']=['client_id'=>$client['client_id'],'redirect_uri'=>$redirect,'challenge'=>$challenge,'state'=>(string)($q['state']??'')];$this->page('Authorize Mail MCP','<p>Allow this ChatGPT connection to send email using configured SMTP domains?</p><form method="post" action="/authorize/approve">'.$this->csrfField().'<button>Allow</button></form><p><a href="/admin">Cancel</a></p>'); }
    private function approve(string $method): void { if($method!=='POST'){$this->httpError(405,'Use POST.');return;}if(!$this->signedIn()){header('Location: /login');return;}$this->csrf();$pending=$_SESSION['pending_auth']??null;unset($_SESSION['pending_auth']);if(!is_array($pending)){$this->httpError(400,'Authorization request expired.');return;}$code=bin2hex(random_bytes(32));$this->store->addCode($code,$pending['client_id'],$pending['redirect_uri'],$pending['challenge'],$pending['state']);$params=['code'=>$code];if($pending['state']!=='')$params['state']=$pending['state'];header('Location: '.$pending['redirect_uri'].'?'.http_build_query($params)); }
    private function token(): void { $this->jsonHeaders();header('Cache-Control: no-store');if($_SERVER['REQUEST_METHOD']!=='POST'){$this->jsonError(405,'invalid_request');return;}parse_str((string)file_get_contents('php://input'),$p);if(($p['grant_type']??'')!=='authorization_code'){$this->jsonError(400,'unsupported_grant_type');return;}$clientId=(string)($p['client_id']??'');$client=$this->store->client($clientId);if(!$client){$this->jsonError(400,'invalid_client');return;}$code=$this->store->redeemCode((string)($p['code']??''),$clientId,(string)($p['redirect_uri']??''));$verifier=(string)($p['code_verifier']??'');if(!$code||!preg_match('/^[A-Za-z0-9._~-]{43,128}$/',$verifier)||!hash_equals($code['challenge'],rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'='))){$this->jsonError(400,'invalid_grant');return;}$token=bin2hex(random_bytes(32));$ttl=(int)$this->store->setting('oauth_token_ttl','3600');$this->store->addToken($token,$clientId,$ttl);echo json_encode(['access_token'=>$token,'token_type'=>'Bearer','expires_in'=>$ttl,'scope'=>'mail.send']); }
    private function jsonHeaders(): void {header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');}
    private function jsonError(int $status,string $error): void {http_response_code($status);echo json_encode(['error'=>$error]);}
    private function signedIn(): bool {return isset($_SESSION['admin_id'])&&$this->store->hasAdmin();}
    private function requirePost(string $method): void {if($method!=='POST'){$this->httpError(405,'Use POST.');return;}$this->csrf();}
    private function csrf(): void {if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??''))){$this->httpError(400,'Invalid form token.');exit;}}
    private function csrfToken(): string {if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
    private function csrfField(): string {return '<input type="hidden" name="csrf" value="'.$this->esc($this->csrfToken()).'">';}
    private function form(string $action,array $fields): string {$html='<form method="post" action="'.$action.'">'.$this->csrfField();foreach($fields as [$name,$label,$type]){$required=$name==='smtp_password'?'':' required';$html.='<label>'.$this->esc($label).'<input'.$required.' name="'.$this->esc($name).'" type="'.$type.'" value="'.($type==='number'&&$name==='smtp_port'?'587':($type==='number'&&$name==='hourly_limit'?'40':($type==='number'&&$name==='daily_limit'?'200':($type==='number'&&$name==='max_recipients'?'10':'')))).'"></label>';}$html.='<button>Save</button></form>';return $html;}
    private function page(string $title,string $content): void {header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store');echo '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$this->esc($title).'</title><style>body{font:16px system-ui;max-width:900px;margin:3rem auto;padding:0 1rem;color:#18212b}h1,h2{margin-top:2rem}label{display:block;margin:12px 0}input{display:block;padding:10px;width:min(100%,520px);box-sizing:border-box;margin-top:4px}button{padding:9px 15px;cursor:pointer}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:8px;border-bottom:1px solid #ddd}code{overflow-wrap:anywhere}.error{color:#a22}</style></head><body><h1>'.$this->esc($title).'</h1>'.$content.'</body></html>';}
    private function encrypt(string $value): string {if($value==='')return ''; $key=base64_decode((string)$this->config['app_key'],true);if(strlen($key)!==SODIUM_CRYPTO_SECRETBOX_KEYBYTES)throw new \RuntimeException('APP_KEY must be base64-encoded 32 bytes.');$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return base64_encode($nonce.sodium_crypto_secretbox($value,$nonce,$key));}
    private function decrypt(string $value): string {if($value==='')return ''; $key=base64_decode((string)$this->config['app_key'],true);if(strlen($key)!==SODIUM_CRYPTO_SECRETBOX_KEYBYTES)throw new \RuntimeException('APP_KEY must be base64-encoded 32 bytes.');$raw=base64_decode($value,true);if($raw===false||strlen($raw)<=SODIUM_CRYPTO_SECRETBOX_NONCEBYTES)return ''; $nonce=substr($raw,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);$plain=sodium_crypto_secretbox_open(substr($raw,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),$nonce,$key);return $plain===false?'':$plain;}
    private function esc(string $s): string {return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private function httpError(int $status,string $message): void {http_response_code($status);header('Content-Type: text/plain; charset=utf-8');echo $message;}
}
